/*
 * Editing the sequence after the agent has built it.
 *
 * The tree is not a gallery of independent images. Each step EDITS the frame
 * before it, so the chain from the avatar to the last frame is a single
 * continuous take — which is what makes the sequence read as a storyboard
 * rather than six unrelated pictures.
 *
 * That is also what makes editing it non-trivial. Swapping frame 3 for an
 * alternate does not just change frame 3: frames 4, 5 and 6 were generated by
 * editing the OLD frame 3, so they now descend from an image that is no longer
 * in the sequence. They are not wrong, exactly — they are answers to a question
 * that was withdrawn.
 *
 * So the operations here do two things: rewire the lineage, and mark what the
 * rewiring invalidated. Nothing is regenerated automatically. Every rebuilt step
 * is a paid generation and twenty seconds of somebody's time, so the decision
 * to spend that belongs to the person, with the count and the cost in front of
 * them.
 *
 * Nothing is deleted either. A replaced frame stays on the canvas as an
 * alternate, because the tree's whole claim is that it shows what happened.
 */
import { FieldValue } from 'firebase-admin/firestore';
import { adminDb } from './firebaseAdmin';

import {
  descendantsOf,
  summarise,
  type LineageNode,
  type RewireResult,
} from './sequence';

/* Re-exported so existing importers keep working and there is still one
   definition of each. */
export {
  lineageOf,
  descendantsOf,
  isOutOfSequence,
  shotPlan,
  rebuildEstimate,
  type LineageNode,
  type RewireResult,
} from './sequence';

async function loadNodes(runId: string): Promise<LineageNode[]> {
  const snap = await adminDb().collection('runs').doc(runId).collection('nodes').orderBy('createdAt').get();
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Omit<LineageNode, 'id'>) }));
}

/**
 * Put `replacementId` where `targetId` sits in the sequence.
 *
 * Both are attempts at the same step with the same parent, so the swap is a
 * re-pointing of children rather than a move: whatever was built on top of the
 * target is now built on top of the replacement. The target stays on the canvas
 * as an alternate.
 */
export async function promoteFrame(runId: string, targetId: string, replacementId: string): Promise<RewireResult> {
  const db = adminDb();
  const nodesRef = db.collection('runs').doc(runId).collection('nodes');
  const nodes = await loadNodes(runId);

  const target = nodes.find((n) => n.id === targetId);
  const replacement = nodes.find((n) => n.id === replacementId);
  if (!target || !replacement) throw new Error('no such frame');
  if (replacement.kind !== 'frame' || target.kind !== 'frame') throw new Error('only frames can be swapped');
  if (!replacement.frameUrl) throw new Error('that frame has no image yet');

  const children = nodes.filter((n) => n.parentId === targetId);

  const batch = db.batch();
  for (const child of children) {
    batch.update(nodesRef.doc(child.id), { parentId: replacementId, stale: true });
  }
  // The replacement takes the target's place in the numbering, so the plan and
  // the canvas agree about which step this is.
  batch.update(nodesRef.doc(replacementId), { stepNo: target.stepNo, stale: false });
  await batch.commit();

  // Everything downstream is stale, not just the direct children: step 5 was
  // edited from step 4, which was edited from the frame that just changed.
  const result = summarise(children.flatMap((c) => [c, ...descendantsOf(nodes, c.id)]));
  if (result.staleIds.length) {
    const b2 = db.batch();
    for (const id of result.staleIds) b2.update(nodesRef.doc(id), { stale: true });
    await b2.commit();
  }
  return result;
}

/**
 * Take a frame out of the sequence.
 *
 * Its children reattach to its parent, so the chain stays unbroken and the
 * steps after it still have something to have been edited from. They are stale
 * for the same reason as a swap: their source changed.
 */
export async function removeFrame(runId: string, nodeId: string): Promise<RewireResult> {
  const db = adminDb();
  const nodesRef = db.collection('runs').doc(runId).collection('nodes');
  const nodes = await loadNodes(runId);

  const node = nodes.find((n) => n.id === nodeId);
  if (!node) throw new Error('no such frame');
  if (node.id === 'root') throw new Error('the source avatar cannot be removed');

  if (node.removedFromSequence) throw new Error('that frame is already out of the sequence');

  /*
   * Only the FRAMES move up.
   *
   * This reattached every child, including rendered clips. A clip belongs to
   * the frame it was made from, not to the sequence, and moving one onto the
   * grandparent made that grandparent read as "already rendered" — its Render
   * button disabled, pointing at a clip generated from a completely different
   * frame. The clip stays with its source, which is also where it is true.
   */
  const children = nodes.filter((n) => n.parentId === nodeId && n.kind === 'frame');
  const newParent = node.parentId ?? 'root';

  const batch = db.batch();
  for (const child of children) batch.update(nodesRef.doc(child.id), { parentId: newParent, stale: true });
  /* Marked rather than deleted: the canvas is a record of what happened, and a
     frame that silently vanishes makes the record a lie.

     Only the one flag. This also wrote status:'rejected', which made the node
     claim two different things about itself — the tree draws "taken out" for
     the flag and "you rejected this" for the status, both absolutely positioned
     at the same offset, so they rendered on top of each other. Taking a frame
     out is not a verdict on it; it is often removed BECAUSE it was fine
     somewhere else. */
  batch.update(nodesRef.doc(nodeId), {
    removedFromSequence: true,
    /* What to hand back if this is undone. Nothing cleared this flag anywhere
       in the codebase, so taking a frame out was a one-way door — and without
       a record of which children were lifted off it, putting it back would be
       guesswork: they now point at its parent, and nothing else says they ever
       pointed here. */
    reattachedOnRemoval: children.map((c) => c.id),
  });
  await batch.commit();

  const result = summarise(children.flatMap((c) => [c, ...descendantsOf(nodes, c.id)]));
  if (result.staleIds.length) {
    const b2 = db.batch();
    for (const id of result.staleIds) b2.update(nodesRef.doc(id), { stale: true });
    await b2.commit();
  }
  return result;
}


/**
 * Put a frame back into the sequence.
 *
 * The counterpart that did not exist. `removedFromSequence` was written in
 * exactly one place and cleared in none, so "Take out of the sequence" was a
 * one-way door: a frame taken out by mistake stayed out for the life of the
 * run, and the only way forward was to pay to regenerate a frame that was
 * sitting right there on the canvas.
 *
 * Undoing a removal means handing back the children the removal lifted off it,
 * which is why removeFrame records them. Those children are stale afterwards
 * for the same reason they were stale when they left: their source changed.
 * The restored frame itself is not — its own parent never moved.
 */
export async function restoreFrame(runId: string, nodeId: string): Promise<RewireResult> {
  const db = adminDb();
  const nodesRef = db.collection('runs').doc(runId).collection('nodes');
  const nodes = await loadNodes(runId);

  const node = nodes.find((n) => n.id === nodeId);
  if (!node) throw new Error('no such frame');
  if (!node.removedFromSequence) throw new Error('that frame is already in the sequence');

  // Only children that still exist, and only ones that have not since been
  // built on somewhere else.
  const returning = (node.reattachedOnRemoval ?? []).filter((id) =>
    nodes.some((n) => n.id === id && n.parentId === (node.parentId ?? 'root')),
  );

  const batch = db.batch();
  batch.update(nodesRef.doc(nodeId), {
    removedFromSequence: FieldValue.delete(),
    reattachedOnRemoval: FieldValue.delete(),
  });
  for (const id of returning) batch.update(nodesRef.doc(id), { parentId: nodeId, stale: true });
  await batch.commit();

  const moved = returning.map((id) => nodes.find((n) => n.id === id)!).filter(Boolean);
  const result = summarise(moved.flatMap((c) => [c, ...descendantsOf(nodes, c.id)]));
  if (result.staleIds.length) {
    const b2 = db.batch();
    for (const id of result.staleIds) b2.update(nodesRef.doc(id), { stale: true });
    await b2.commit();
  }
  return result;
}
